# Try: Fill the triangle formed by vertices: leftmost, rightmost, topmost marker
# Vertices: (3,5) [leftmost], (2,7) [rightmost], (5,6) [bottom] - these form triangle
# But what about point-in-triangle INCLUDING edges?

test_grid = [
    [8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 3, 3, 3, 3],
    [8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8],
    [8, 8, 8, 8, 8, 8, 8, 2, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8],
    [8, 8, 8, 8, 8, 2, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8],
    [8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8],
    [8, 8, 8, 8, 8, 8, 2, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8],
    [8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8],
    [8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8],
    [8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8],
    [8, 8, 8, 8, 8, 3, 3, 3, 3, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8],
]

output = [row[:] for row in test_grid]
markers = [(2, 7), (3, 5), (5, 6)]
v1 = (2, 7)  # top marker
v2 = (3, 5)  # left marker  
v3 = (5, 6)  # bottom marker

def point_in_triangle(p, a, b, c, include_edges=True):
    """Check if point p is inside/boundary of triangle abc"""
    def cross(pa, pb, pc):
        return (pb[0] - pa[0]) * (pc[1] - pa[1]) - (pb[1] - pa[1]) * (pc[0] - pa[0])

    c1 = cross(p, a, b)
    c2 = cross(p, b, c)
    c3 = cross(p, c, a)

    if include_edges:
        if c1 == 0 or c2 == 0 or c3 == 0:
            return True
        if c1 >= 0 and c2 >= 0 and c3 >= 0:
            return c1 > 0 or c2 > 0 or c3 > 0
        elif c1 <= 0 and c2 <= 0 and c3 <= 0:
            return c1 < 0 or c2 < 0 or c3 < 0
        return False
    else:
        if c1 == 0 or c2 == 0 or c3 == 0:
            return False
        return ((c1 > 0 and c2 > 0 and c3 > 0) or 
                (c1 < 0 and c2 < 0 and c3 < 0))

for r in range(10):
    for c in range(19):
        p = (r, c)
        if p in markers:
            output[r][c] = 2
        elif point_in_triangle(p, v1, v2, v3, include_edges=True):
            output[r][c] = 4
        else:
            output[r][c] = 3

# Preserve original 3s - none should be inside this small triangle anyway
for (r, c) in [(0, 15), (0, 16), (0, 17), (0, 18), (9, 5), (9, 6), (9, 7), (9, 8)]:
    output[r][c] = 3

print("Triangle from 3 markers (with edges) → 4, rest → 3, markers→2:")
for row in output:
    print(row)

